        #page-2 details[open] > .equipment-list { padding-bottom: 15px; }
        .party-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 15px; margin-top: 10px; }
        .party-member-card { background-color: #f0ede3; border: 1px solid var(--border-color); border-radius: 6px; padding: 15px; cursor: pointer; transition: transform 0.2s ease, box-shadow 0.2s ease; box-shadow: 1px 1px 3px rgba(0,0,0,0.1); }
        .party-member-card:hover { transform: translateY(-2px); box-shadow: 2px 2px 6px rgba(0,0,0,0.2); }
        .party-member-header { display: flex; align-items: center; margin-bottom: 8px; }
        .party-member-action-icon { font-size: 1.2em; margin-right: 10px; }
        .party-member-name { font-family: var(--font-ui); font-weight: 700; font-size: 1.05em; color: var(--dark-leather-bg); }
        .party-member-action-text { font-family: var(--font-ui); font-size: 0.85em; color: #777; margin-bottom: 5px; }
        .party-member-class { font-family: var(--font-main); font-style: italic; font-size: 0.9em; color: #666; }
        .preview-container { max-width: 100%; }
        #character-sheet-label { display: block; margin-bottom: 6px; font-weight: bold; font-family: var(--font-ui); color: var(--dark-leather-bg); font-size: 1.1em; }
        #character-summary { white-space: pre-wrap; background-color: #e9e4d9; text-align: left; font-size: 0.9em; height: 400px; resize: vertical; width: 100%; padding: 15px; border: 1px solid #a58e72; border-radius: 4px; color: #2c2a2a; font-family: var(--font-code); line-height: 1.6; box-sizing: border-box; }

    </style>
</head>
<body>

<div class="log-wrapper">
    <div class="border-flow"></div>
    <div class="inner-border"></div>

    <div class="content-container">
        <div class="title-area">
            <div class="decorative-line"></div>
            <h2 id="board-title"></h2>
        </div>

        <div id="quest-list-container" class="view-page active-view">
        </div>

        <div id="status-page-container" class="view-page">
            <details class="gs-status-wrapper" open>
                <summary class="gs-summary">
                    <div class="summary-left">
                        <span class="summary-icon emoji-icon">📜</span>
                        <span id="summary-name"></span>
                    </div>
                    <div class="summary-right">
                        <span id="summary-rank" class="rank-badge"></span>
                    </div>
                </summary>
                <div class="gs-main-content">
                    <div id="page-1" class="page active">
                        <div id="time-log-header"></div>
                        <div class="status-columns">
                            <div class="status-column" id="surface-status-column">
                                <h4><span class="icon emoji-icon">👁️</span>表层状态</h4>
                            </div>
                            <div class="status-column" id="internal-status-column">
                                <h4><span class="icon emoji-icon">🧠</span>身心状态</h4>
                            </div>
                        </div>
                    </div>
                    <div id="page-2" class="page">
                        <details open>
                            <summary><span class="icon emoji-icon">🎒</span>携带道具</summary>
                            <ul id="equipment-list-item" class="equipment-list"></ul>
                        </details>
                        <h4><span class="icon emoji-icon">🤝</span>同行队伍</h4>
                        <div id="party-list" class="party-grid"></div>
                        <h4><span class="icon emoji-icon">📖</span>冒险日志</h4>
                        <div class="adventure-log">
                            <p id="log-entry"></p>
                        </div>
                    </div>
                    <div id="page-3" class="page">
                        <div class="preview-container">
                            <label id="character-sheet-label" for="character-summary">角色卡预览</label>
                            <textarea id="character-summary" readonly></textarea>
                        </div>
                    </div>
                    <div class="gs-pagination">
                        <button id="nav-page-1" class="nav-button active">状态</button>
                        <button id="nav-page-2" class="nav-button">日志</button>
                        <button id="nav-page-3" class="nav-button">角色卡</button>
                    </div>
                </div>
            </details>
        </div>
    </div>

    <div class="main-menubar">
        <button id="btn-view-log" class="menu-button active">冒险日志</button>
        <button id="btn-view-status" class="menu-button">状态栏</button>
    </div>

    <div class="footer-signature">
        Adventurers' Guild
    </div>
</div>

<script>
// 此处的第一个<script>块（数据处理逻辑）保持不变
// The first <script> block (data processing logic) remains unchanged.
// Global variable to hold the current character state.
let currentCharacterData = {};

// 自然语言格式的初始游戏文本
const initialGameText = `$1`;

/**
 * 自然语言到变量格式的映射表
 */
const naturalLanguageMapping = {
    // 基本信息
    '角色名': 'name',
    '是否新手': 'isNewbie',
    '等级': 'rank',
    '等级样式': 'rankClass',

    // 核心数值
    '天命': 'destiny',
    '生命值': 'life',
    '疲劳度': 'fatigue',

    // 环境信息
    '星期': 'environment.weekday',
    '日期': 'environment.date',
    '时段': 'environment.period',
    '时间': 'environment.time',
    '地点': 'environment.location',
    '天气': 'environment.weather',
    '温度感': 'environment.temperature_feel',
    '光源': 'environment.lighting_source',
    '光照等级': 'environment.lighting_level',

    // 表层状态 (这些会被特殊处理)
    '服装': 'surface_status.服装',
    '姿势': 'surface_status.姿势',
    '检视(装备)': 'surface_status.检视（装备）',

    // 内在状态 (这些会被特殊处理)
    '心里所想': 'internal_status.心里所想',
    '理智程度': 'internal_status.理智程度',

    // 装备和队伍 (特殊处理)
    '携带道具': 'equipment.items',
    '队伍成员': 'party',
    '冒险日志': 'log',

    // 角色卡信息
    '角色种族': 'sheetData.race',
    '角色性别': 'sheetData.gender',
    '角色年龄': 'sheetData.age',
    '角色出身': 'sheetData.origin',
    '角色技能': 'sheetData.skills',

    // 属性
    '力量': 'sheetData.attributes.str',
    '敏捷': 'sheetData.attributes.dex',
    '感知': 'sheetData.attributes.per',
    '知识': 'sheetData.attributes.knw',
    '魅力': 'sheetData.attributes.chr',
    '信仰力': 'sheetData.attributes.faith',
    '魔力': 'sheetData.attributes.mana',

    // 资产
    '金币': 'sheetData.assets.currency.gold',
    '银币': 'sheetData.assets.currency.silver',
    '铜币': 'sheetData.assets.currency.copper',
    '贵重品': 'sheetData.assets.valuables'
};

/**
 * 解析自然语言格式的gamedata并转换为变量格式
 */
function parseNaturalLanguageGameData(gameDataString) {
    const newData = {};
    const lines = gameDataString.trim().split('\n');

    lines.forEach(line => {
        const colonIndex = line.indexOf(':');
        if (colonIndex === -1) return;

        const naturalKey = line.substring(0, colonIndex).trim();
        let value = line.substring(colonIndex + 1).trim();

        // 获取对应的变量路径
        const varPath = naturalLanguageMapping[naturalKey];
        if (!varPath) {
            console.warn(`未知的自然语言键: ${naturalKey}`);
            return;
        }

        // 特殊处理某些值类型
        value = processSpecialValues(naturalKey, value);

        // 设置到数据对象中
        setNestedValue(newData, varPath, value);
    });

    return newData;
}

/**
 * 处理特殊的值类型转换
 */
function processSpecialValues(key, value) {
    // 处理布尔值
    if (key === '是否新手') {
        return value === '是' || value === 'true';
    }

    // 处理数值对 (如 "5/10", "23/23")
    if (['天命', '生命值', '疲劳度'].includes(key)) {
        const parts = value.split('/');
        if (parts.length === 2) {
            return {
                current: parseInt(parts[0].trim()),
                max: parseInt(parts[1].trim())
            };
        }
    }

    // 处理数字
    if (!isNaN(value) && value.trim() !== '') {
        return Number(value);
    }

    // 处理表层状态和内在状态
    if (key.startsWith('表层状态') || key.startsWith('内在状态')) {
        // 这些会在后续特殊处理
        return value;
    }

    // 处理携带道具
    if (key === '携带道具') {
        return parseEquipmentString(value);
    }

    // 处理队伍成员
    if (key === '队伍成员') {
        return parsePartyString(value);
    }

    // 处理贵重品
    if (key === '贵重品') {
        return value.split(',').map(item => item.trim());
    }

    return value;
}

/**
 * 解析装备字符串
 */
function parseEquipmentString(equipStr) {
    const items = [];
    const parts = equipStr.split(',');

    parts.forEach(part => {
        const trimmed = part.trim();
        // 方案一：为正则表达式添加 'u' 标记以支持Unicode
        const match = trimmed.match(/^(.+?)(.+?)×(\d+)$/u);
        if (match) {
            items.push({
                icon: match[1],
                name: match[2],
                count: parseInt(match[3])
            });
        }
    });

    return items;
}

/**
 * 解析队伍成员字符串
 */
function parsePartyString(partyStr) {
    const members = [];
    const parts = partyStr.split(',');

    parts.forEach(part => {
        const trimmed = part.trim();
        const match = trimmed.match(/^(.+?)(.+?)\((.+?)，(.+?)\)$/);
        if (match) {
            members.push({
                icon: match[1],
                name: match[2],
                class: match[3],
                action: match[4]
            });
        }
    });

    return members;
}

/**
 * 设置嵌套对象的值
 */
function setNestedValue(obj, path, value) {
    // 处理特殊的状态路径
    if (path.startsWith('surface_status.') || path.startsWith('internal_status.')) {
        const [category, label] = path.split('.');
        if (!obj[category]) obj[category] = [];

        // 确定图标
        const iconMap = {
            '服装': '👚',
            '姿势': '🙋‍♀️',
            '检视（装备）': '🛡️',
            '心里所想': '💭',
            '理智程度': '💎'
        };

        obj[category].push({
            icon: iconMap[label] || '📝',
            label: label,
            value: value
        });
        return;
    }

    const keys = path.split('.');
    let current = obj;

    for (let i = 0; i < keys.length - 1; i++) {
        if (!current[keys[i]]) {
            current[keys[i]] = {};
        }
        current = current[keys[i]];
    }

    current[keys[keys.length - 1]] = value;
}

/**
 * 从自然语言gametext更新UI
 */
function updateUIFromGameText(gameTextString) {
    if (!gameTextString) return;
    const sceneTextMatch = gameTextString.match(/<scenetext>([\s\S]*?)<\/scenetext>/);
    const gameDataMatch = gameTextString.match(/<gamedata>([\s\S]*?)<\/gamedata>/);

    if (sceneTextMatch) {
        updateAdventureLog(sceneTextMatch[1]);
    }

    if (gameDataMatch) {
        const newCharacterData = parseNaturalLanguageGameData(gameDataMatch[1]);
        // 合并新数据
        currentCharacterData = Object.assign({}, currentCharacterData, newCharacterData);
        renderStatus(currentCharacterData);
    }
}

/**
 * 添加冒险日志条目
 */
function updateAdventureLog(sceneText) {
    if (!sceneText || sceneText.trim() === '') return;

    const logContainer = document.getElementById('quest-list-container');
    const entryDiv = document.createElement('div');
    entryDiv.className = 'log-entry-item';

    const timeStamp = new Date();
    const timeString = timeStamp.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });

    entryDiv.innerHTML = `<span class="log-timestamp">${timeString}</span><span>${sceneText.trim()}</span>`;

    logContainer.appendChild(entryDiv);
    logContainer.scrollTop = logContainer.scrollHeight;
}

// --- 渲染函数保持不变 ---
function getDestinyDescription(current, max) {
    const percentage = (current / max) * 100;
    if (percentage >= 90) return "天命完全向我们倾斜";
    if (percentage >= 75) return "天命正向我们展露微笑";
    if (percentage >= 60) return "天平略微倾向我方";
    if (percentage >= 40) return "天平正寻求着平衡";
    if (percentage >= 20) return "天命似乎有所迟疑";
    return "命运的钟摆正远离我们";
}

function getLifeDescription(current, max) {
    if (current <= 0) return "失去意识";
    const percentage = (current / max) * 100;
    if (percentage >= 100) return "毫发无伤";
    if (percentage >= 80) return "轻伤";
    if (percentage >= 50) return "负伤";
    if (percentage >= 20) return "身负重伤";
    return "濒死";
}

function getFatiguePenaltyDescription(level) {
    switch(level) {
        case 0: return "无";
        case 1: return "所有判定-1";
        case 2: return "所有判定-2，移动力减半";
        case 3: return "所有判定-3，生命力&移动力减半";
        case 4: return "所有判定-4，陷入昏迷";
        case 5: return "死亡";
        default: return "未知";
    }
}

function generateCharacterSheet(sheetData, isNewbie) {
    if (!sheetData) return "角色卡数据缺失。";

    const assetsLabel = isNewbie ? "初始资产" : "资产";
    const attr = sheetData.attributes || {};
    let assetsString = "";

    if(sheetData.assets){
        if(sheetData.assets.currency){
            const currencyParts = [];
            if(sheetData.assets.currency.gold) currencyParts.push(`${sheetData.assets.currency.gold} 金币`);
            if(sheetData.assets.currency.silver) currencyParts.push(`${sheetData.assets.currency.silver} 银币`);
            if(sheetData.assets.currency.copper) currencyParts.push(`${sheetData.assets.currency.copper} 铜币`);
            if(currencyParts.length > 0) {
                assetsString += `- 货币: ${currencyParts.join(', ')}\n`;
            }
        }
        if(sheetData.assets.valuables && sheetData.assets.valuables.length > 0){
            assetsString += `- 贵重品:\n` + sheetData.assets.valuables.map(item => `   - ${item}`).join('\n');
        }
    }

    return `### 《哥布林杀手TRPG》冒险者登记卡\n**姓名:** ${sheetData.name || 'N/A'} | **种族:** ${sheetData.race || 'N/A'} | **性别:** ${sheetData.gender || 'N/A'} | **年龄:** ${sheetData.age || 'N/A'}\n**出身:** ${sheetData.origin || 'N/A'}\n**技能:** ${sheetData.skills || 'N/A'}\n---\n**属性:**\n- 力量 (STR): ${attr.str || 0}\n- 敏捷 (DEX): ${attr.dex || 0}\n- 感知 (PER): ${attr.per || 0}\n- 知识 (KNW): ${attr.knw || 0}\n- 魅力 (CHR): ${attr.chr || 0}\n- 信仰力 (Faith): ${attr.faith || 0}\n- 魔力 (Mana): ${attr.mana || 0}\n---\n**${assetsLabel}:**\n${assetsString || '- 无'}\n`;
}

function renderStatus(data) {
    if (!data || Object.keys(data).length === 0) return;

    // 基本信息渲染
    document.getElementById('summary-name').textContent = data.name || "未知角色";
    const rankBadge = document.getElementById('summary-rank');
    rankBadge.className = `rank-badge ${data.rankClass || 'rank-porcelain'}`;
    rankBadge.textContent = data.rank || "无等级";

    // 时间和环境信息
    const timeLogHeader = document.getElementById('time-log-header');
    if (data.environment) {
       timeLogHeader.innerHTML = `<p><span class="icon emoji-icon">⏱️</span> ${data.environment.weekday || ''}, ${data.environment.date || ''} ${data.environment.period || ''} ${data.environment.time || ''} (${data.environment.temperature_feel || ''})</p><p><span class="icon emoji-icon">📍</span> ${data.environment.location || ''} - ${data.environment.weather || ''} | <span class="icon emoji-icon">💡</span>光照: ${data.environment.lighting_level || ''} (来源: ${data.environment.lighting_source || ''})</p><p id="destiny-status"><span class="icon emoji-icon">⚖️</span> 天命: ${data.destiny ? getDestinyDescription(data.destiny.current, data.destiny.max) : '未知'}</p>`;
    }

    // 表层状态
    const surfaceContainer = document.getElementById('surface-status-column');
    surfaceContainer.innerHTML = '<h4><span class="icon emoji-icon">👁️</span>表层状态</h4>';
    if(data.surface_status && Array.isArray(data.surface_status)) {
        data.surface_status.forEach(item => {
            const div = document.createElement('div');
            div.className = 'status-item';
            div.innerHTML = `<strong><span class="emoji-icon">${item.icon}</span> ${item.label}:</strong> ${item.value}`;
            surfaceContainer.appendChild(div);
        });
    }

    // 内在状态
    const internalContainer = document.getElementById('internal-status-column');
    internalContainer.innerHTML = '<h4><span class="icon emoji-icon">🧠</span>身心状态</h4>';

    // 生命值和疲劳度
    if(data.life) {
        const lifeStatus = document.createElement('div');
        lifeStatus.className = 'status-item';
        lifeStatus.innerHTML = `<strong><span class="emoji-icon">❤️</span> 生命值:</strong> ${data.life.current}/${data.life.max} (${getLifeDescription(data.life.current, data.life.max)})`;
        internalContainer.appendChild(lifeStatus);
    }

    if(data.fatigue) {
        const fatigueStatus = document.createElement('div');
        fatigueStatus.className = 'status-item';
        fatigueStatus.innerHTML = `<strong><span class="emoji-icon">😪</span> 疲劳度:</strong> ${data.fatigue.current}/${data.fatigue.max} <span class="penalty">(${getFatiguePenaltyDescription(data.fatigue.current)})</span>`;
        internalContainer.appendChild(fatigueStatus);
    }

    // 其他内在状态
    if(data.internal_status && Array.isArray(data.internal_status)) {
        data.internal_status.forEach(item => {
            const div = document.createElement('div');
            div.className = 'status-item';
            div.innerHTML = `<strong><span class="emoji-icon">${item.icon}</span> ${item.label}:</strong> ${item.value}`;
            internalContainer.appendChild(div);
        });
    }

    // 冒险日志
    if(data.log) document.getElementById('log-entry').textContent = data.log;

    // 装备列表
    const itemListEl = document.getElementById('equipment-list-item');
    itemListEl.innerHTML = '';
    if(data.equipment && data.equipment.items && Array.isArray(data.equipment.items)) {
        data.equipment.items.forEach(item => {
            const li = document.createElement('li');
            li.innerHTML = `<span class="item-icon emoji-icon">${item.icon}</span><span class="item-name">${item.name}</span><span class="item-count">×${item.count}</span>`;
            itemListEl.appendChild(li);
        });
    }

    // 队伍成员
    const partyListEl = document.getElementById('party-list');
    partyListEl.innerHTML = '';
    if (data.party && Array.isArray(data.party) && data.party.length > 0) {
        data.party.forEach(member => {
            const div = document.createElement('div');
            div.className = 'party-member-card';
            div.innerHTML = `<div class="party-member-header"><span class="party-member-action-icon emoji-icon">${member.icon}</span><div class="party-member-name">${member.name}</div></div><div class="party-member-action-text">${member.action}</div><div class="party-member-class">${member.class}</div>`;
            partyListEl.appendChild(div);
        });
    }

    // 角色卡
    if (data.sheetData && data.name) {
        data.sheetData.name = data.name;
    }
    const rawSheet = generateCharacterSheet(data.sheetData, data.isNewbie);
    const cleanedSheet = rawSheet.replace(/### /g, '').replace(/\*\*/g, '').replace(/---/g, '\n────────────────────\n').replace(/- /g, '  ');
    document.getElementById('character-summary').value = cleanedSheet;
}

// --- 事件监听器和初始化 ---
document.addEventListener('DOMContentLoaded', function() {
    // 初始化标题
    const boardTitleElement = document.getElementById('board-title');
    boardTitleElement.innerHTML = `⚔️ 冒险日志 ⚔️`;

    // 从自然语言gametext初始化UI，这会自动处理scenetext
    updateUIFromGameText(initialGameText);

    // 状态组件内部分页
    const statusNavButtons = document.querySelectorAll('.gs-pagination .nav-button');
    const statusPages = document.querySelectorAll('.gs-main-content .page');

    function switchStatusPage(targetPageId) {
        statusPages.forEach(page => page.classList.remove('active'));
        statusNavButtons.forEach(button => button.classList.remove('active'));
        document.getElementById(targetPageId).classList.add('active');
        document.querySelector(`.gs-pagination button[id='nav-${targetPageId}']`).classList.add('active');
    }

    statusNavButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            if (e.currentTarget.id.startsWith('nav-')) {
                const pageId = e.currentTarget.id.replace('nav-', '');
                switchStatusPage(pageId);
            }
        });
    });

    // 主视图切换
    const logViewButton = document.getElementById('btn-view-log');
    const statusViewButton = document.getElementById('btn-view-status');
    const logViewContainer = document.getElementById('quest-list-container');
    const statusViewContainer = document.getElementById('status-page-container');

    logViewButton.addEventListener('click', () => {
        logViewButton.classList.add('active');
        statusViewButton.classList.remove('active');
        logViewContainer.classList.add('active-view');
        statusViewContainer.classList.remove('active-view');
        boardTitleElement.innerHTML = `⚔️ 冒险日志 ⚔️`;
    });

    statusViewButton.addEventListener('click', () => {
        statusViewButton.classList.add('active');
        logViewButton.classList.remove('active');
        statusViewContainer.classList.add('active-view');
        logViewContainer.classList.remove('active-view');
        boardTitleElement.innerHTML = `📜 角色状态栏 📜`;
    });
});
</script>

</body>
</html>
