     * It's designed to be robust for dynamically injected content.
     */
    function initializeTaskboards() {
        // Find all component wrappers that have not been marked as 'initialized' yet.
        const wrappers = document.querySelectorAll('.taskboard-wrapper:not(.initialized)');

        wrappers.forEach(container => {
            // Mark this container as initialized to prevent this script from running on it again.
            container.classList.add('initialized');

            // Safely find elements only within this specific container
            const titleDataElement = container.querySelector('.taskboard-dynamic-title');
            const boardTitleElement = container.querySelector('.taskboard-title');
            const questListContainer = container.querySelector('.taskboard-list-container');

            if (titleDataElement && boardTitleElement && questListContainer) {
                const dynamicTitle = titleDataElement.textContent.trim();
                const defaultTitleText = '冒险者公会任务板';

                if (dynamicTitle && dynamicTitle !== '$1' && dynamicTitle.length > 0) {
                    boardTitleElement.innerHTML = `⚔️ ${dynamicTitle} ⚔️`;
                }

                if (boardTitleElement.textContent.trim().includes(defaultTitleText)) {
                    questListContainer.style.display = 'block';
                } else {
                    questListContainer.style.display = 'none';
                }
            }
        });
    }

    // Run the initialization function. For dynamically added content,
    // this script will execute as soon as it's parsed.
    // We wrap it in a try-catch block for extra safety in complex environments.
    try {
        initializeTaskboards();
    } catch (e) {
        console.error("Failed to initialize taskboard:", e);
    }
})();
</script>

