  description: 冒险者生存的基石，其选择直接关系到面对物理攻击时的生存率。
{
  "铠甲_armor": {
    "布甲": {
      "基础衣物": {
        "description": "普通衣物，无实际防御力。",
        "price": "15银币",
        "armor_value": 0,
        "dodge_modifier": 0,
        "stealth_penalty": 0,
        "type": "布甲",
        "requirements": {}
