entries.content:
# 道具列表：魔法装备 (Magical Equipment)
  description: 经由魔法强化或本身就蕴含魔力的稀有物品，是资深冒险者的追求。其制造技术大多已失传，主要通过探索遗迹或击败强大敌人获得。
  acquisition: 极难获得。偶尔会在大城市的武器店或黑市出现，价格昂贵。
  {
  "魔法武器_template": {
    "name_format": "魔法[武器名] +n",
    "description": "获得命中修正与威力加成(+n)，并能伤害免疫普通武器的怪物。",
    "generation_rules": {
      "hit_modifier_bonus": "n",
      "damage_bonus": "n"
    },
    "price_modifier": {
      "+1": { "multiplier": 5, "add": 100 },
      "+2": { "multiplier": 10, "add": 1000 },
      "+3": { "multiplier": 30, "add": 10000 }
    },
    "notes": "能伤害特殊灵体或魔法生物。"
  },
  "魔法防具_template": {
    "name_format": "魔法[防具/盾牌名] +n",
    "description": "获得回避修正与护甲值/格挡值加成(+n)。",
    "generation_rules": {
      "dodge_modifier_bonus": "n",
      "armor_value_bonus": "n",
      "block_value_bonus": "n"
    },
    "price_modifier": {
      "+1": { "multiplier": 5, "add": 100 },
      "+2": { "multiplier": 10, "add": 1000 },
      "+3": { "multiplier": 30, "add": 10000 }
    }
  },
  "魔法饰品_accessories": {
    "能力强化戒指": {
      "price": "2000银币",
      "effect_description": "佩戴者的体力/魂魄/技巧/智力点数之一获得+1加成。",
      "effects": {
        "attribute_bonus": { "type": "any_primary", "value": 1 }
      },
      "notes": "更高级版本价格指数级增长。"
    },
    "水下呼吸戒指": {
      "price": "500银币",
      "effect_description": "每日一次，获得持续8小时的水下呼吸能力。",
      "effects": {
        "active_ability": "水下呼吸"
      }
    },
    "法术抗性戒指": {
      "price": "1000银币",
      "effect_description": "法术抵抗检定获得+2加值。",
      "effects": {
        "spell_resistance_check": 2
      }
    },
    "法术屏障戒指": {
      "price": "1000银币",
      "effect_description": "一次性使用，在单次法术抵抗检定中获得+4加值，使用后粉碎。",
      "effects": {
        "consumable_bonus": { "check_type": "spell_resistance", "value": 4 }
      }
    },
    "武器专精护腕": {
      "price": "1000银币",
      "effect_description": "使用特定类型武器时，命中与伤害检定+1。",
      "effects": {
        "conditional_bonus": { "condition": "specific_weapon_type", "hit_modifier": 1, "damage": 1 }
      }
    },
    "体术精通手环": {
      "price": "1000银币",
      "effect_description": "闪避及其他运动系判定+1。",
      "effects": {
        "dodge_check": 1,
        "athletics_check": 1
      }
    }
  },
  "魔法卷轴_scrolls": {
    "魔法卷轴": {
      "price_formula": "(封存咒文达成值 * 50) + 500",
      "effect_description": "封存一次性咒语，非施法者也能使用。使用后卷轴燃尽。",
      "effects": {
        "consumable_spell": true
      }
    }
  }
}

